"use client";

/**
 * VESPER Intelligence on the Command Centre: prioritised insights, a discreet Ask VESPER box, and the shift briefing.
 *
 * Everything shown is generated by the rules in lib/intelligence-rules.ts from records that already exist. Nothing here is a record of its
 * own, every insight and answer links to its source, and money only appears for roles allowed to see it. The system calculates, the text
 * explains, and a person decides: no button on these panels changes anything except by opening the record where the work is done.
 */
import { ArrowRight, Check, ChartNoAxesColumn, ClipboardCheck, Send, Sparkles, Truck, Wrench, Box } from "lucide-react";
import Link from "next/link";
import { useMemo, useState } from "react";
import { answerQuestion, buildBriefing, buildInsights, exampleQuestions, type Answer, type Insight, type IntelligenceInputs } from "@/lib/intelligence-rules";
import { useImpact } from "./use-impact";
import { useLogistics } from "./use-logistics";

const insightIcon = { production: ChartNoAxesColumn, shipment: Truck, equipment: Wrench, readiness: Box } as const;

/** Everything the rules need: the records the Overview already loaded, plus the impact estimate and shipments. */
export function useIntelligenceInputs(base: Pick<IntelligenceInputs, "now" | "issues" | "equipment" | "readiness" | "shifts">): IntelligenceInputs | null {
  const impact = useImpact();
  const logistics = useLogistics();
  const { now, issues, equipment, readiness, shifts } = base;
  return useMemo(() => {
    if (!logistics.data) return null;
    return { now, issues, equipment, readiness, shifts, shipments: logistics.data.shipments, requests: logistics.data.requests, impact: impact.data ?? null };
  }, [now, issues, equipment, readiness, shifts, logistics.data, impact.data]);
}

/** One of the Overview's intelligence panels. It waits for the records it needs and shows nothing until it has them. */
export function IntelligenceSlot({ part, base }: { part: "insights" | "briefing"; base: Pick<IntelligenceInputs, "now" | "issues" | "equipment" | "readiness" | "shifts"> }) {
  const inputs = useIntelligenceInputs(base);
  if (!inputs) return null;
  return part === "insights" ? <IntelligencePanel inputs={inputs} /> : <ShiftBriefingPanel inputs={inputs} />;
}

export function IntelligencePanel({ inputs }: { inputs: IntelligenceInputs }) {
  const insights = useMemo(() => buildInsights(inputs), [inputs]);
  const [all, setAll] = useState(false);
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState<{ asked: string; result: Answer } | null>(null);
  const shown = all ? insights : insights.slice(0, 2);

  const ask = (text: string) => {
    const asked = text.trim();
    if (asked.length < 3) return;
    setQuestion(asked);
    setAnswer({ asked, result: answerQuestion(asked, inputs) });
  };

  return (
    <article className="card intel" aria-labelledby="intel-title">
      <header className="intel__head">
        <span className="intel__icon" aria-hidden="true"><Sparkles /></span>
        <div>
          <h3 id="intel-title">VESPER Intelligence <small>Generated from your records</small></h3>
          <p>Operational insights, impact and recommended actions.</p>
        </div>
      </header>

      {shown.length === 0 ? <p className="intel__empty">Nothing on record needs attention right now.</p> : (
        <ul className="intel__list" aria-label="Insights">
          {shown.map((item) => <InsightRow key={item.id} item={item} showWhy={all} />)}
        </ul>
      )}
      {insights.length > 2 ? <button className="link-button intel__more" onClick={() => setAll(!all)} aria-expanded={all}>{all ? "Show fewer" : `Show all ${insights.length} with why it matters`}</button> : null}

      <form className="intel__ask" onSubmit={(event) => { event.preventDefault(); ask(question); }}>
        <label className="visually-hidden" htmlFor="ask-vesper">Ask VESPER a question about your operations</label>
        <input id="ask-vesper" value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="Ask VESPER a question about your operations…" autoComplete="off" />
        <button type="submit" className="intel__send" aria-label="Ask" disabled={question.trim().length < 3}><Send /></button>
      </form>

      {answer ? (
        <div className="intel__answer" role="status" aria-live="polite">
          <p className="intel__asked">{answer.asked}</p>
          <p>{answer.result.text}</p>
          {answer.result.missing.length > 0 ? <p className="intel__missing"><strong>Not available:</strong> {answer.result.missing.join(" ")}</p> : null}
          {answer.result.links.length > 0 ? (
            <p className="intel__links">Based on: {answer.result.links.map((link) => <Link key={link.href + link.label} href={link.href}>{link.label}</Link>)}</p>
          ) : null}
          {answer.result.topic === "unsupported" ? (
            <ul className="intel__examples" aria-label="Questions you can ask">
              {exampleQuestions.map((example) => <li key={example}><button type="button" className="link-button" onClick={() => ask(example)}>{example}</button></li>)}
            </ul>
          ) : null}
        </div>
      ) : null}
    </article>
  );
}

function InsightRow({ item, showWhy }: { item: Insight; showWhy: boolean }) {
  const Icon = insightIcon[item.kind];
  return (
    <li className="intel__item">
      <span className="intel__item-icon" aria-hidden="true"><Icon /></span>
      <div className="intel__item-body">
        <strong>{item.title}</strong>
        <p>{item.summary}</p>
        {showWhy ? <small>{item.why}</small> : null}
      </div>
      <Link className="button button--quiet button--small" href={item.action.href}>{item.action.label} <ArrowRight /></Link>
    </li>
  );
}

/** The shift briefing, assembled from records. It is a draft for a supervisor to review: it is never sent or approved from here. */
export function ShiftBriefingPanel({ inputs }: { inputs: IntelligenceInputs }) {
  const briefing = useMemo(() => buildBriefing(inputs), [inputs]);
  return (
    <article className="card intel-briefing" aria-labelledby="briefing-title">
      <header className="card__header">
        <div><span className="eyebrow">Intelligence summary</span><h2 id="briefing-title">Shift briefing</h2></div>
      </header>
      <ul className="intel-briefing__list">
        {briefing.lines.map((line) => (
          <li key={line.id} className={`intel-briefing__line intel-briefing__line--${line.tone}`}>
            <span aria-hidden="true">{line.tone === "good" ? <Check /> : <ClipboardCheck />}</span>
            {line.href ? <Link href={line.href}>{line.text}</Link> : line.text}
          </li>
        ))}
      </ul>
      {briefing.nextShift.length > 0 ? (
        <div className="intel-briefing__next">
          <small>Suggested priorities for the next shift</small>
          <ul>{briefing.nextShift.map((line) => <li key={line.id}>{line.href ? <Link href={line.href}>{line.text}</Link> : line.text}</li>)}</ul>
        </div>
      ) : null}
      <p className="card__footnote">Generated from records. A supervisor reviews and sends the handover; nothing is approved here.</p>
      <div className="intel-briefing__footer">
        <Link className="button button--quiet" href={briefing.shiftId ? `/shifts/${briefing.shiftId}/handover` : "/shifts/handover"}>View full briefing <ArrowRight /></Link>
      </div>
    </article>
  );
}
